/**
 * Copies Leaflet's JS and CSS out of node_modules into src/map/leafletBundle.js as strings.
 * The map page is loaded from a string with no network, so it must carry Leaflet itself: a CDN link would leave
 * the map dead on a phone with no connection, which is exactly when the app is meant to keep working.
 *
 *   node scripts/buildLeafletBundle.js     (run again only after upgrading the leaflet package)
 */
const fs = require('fs');
const path = require('path');

const dist = path.join(__dirname, '..', 'node_modules', 'leaflet', 'dist');
const version = require('leaflet/package.json').version;
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');

const out = [
  `// Generated by scripts/buildLeafletBundle.js from leaflet ${version} (BSD-2-Clause). Do not edit.`,
  `module.exports = { version: ${JSON.stringify(version)}, js: ${JSON.stringify(js)}, css: ${JSON.stringify(css)} };`,
  '',
].join('\n');

fs.writeFileSync(path.join(__dirname, '..', 'src', 'map', 'leafletBundle.js'), out);
console.log(`leafletBundle.js written (${Math.round(out.length / 1024)} KB, leaflet ${version})`);
